impl ClientCapabilities {
    /// `ClientCapabilities.Resolve()` — collapses optional fields into the resolved
    /// view used internally after capabilities are negotiated.
    pub fn resolve(__this: Option<&Self>) -> ResolvedClientCapabilities {
        let Some(__v) = __this else {
            return ResolvedClientCapabilities::default();
        };
        ResolvedClientCapabilities {
            workspace: WorkspaceClientCapabilities::resolve(__v.workspace.as_ref()),
            text_document: TextDocumentClientCapabilities::resolve(__v.text_document.as_ref()),
            window: WindowClientCapabilities::resolve(__v.window.as_ref()),
            general: GeneralClientCapabilities::resolve(__v.general.as_ref()),
            experimental: ExperimentalClientCapabilities::resolve(__v.experimental.as_ref()),
            vs_supports_visual_studio_extensions: __v
                .vs_supports_visual_studio_extensions
                .unwrap_or_default(),
            vs_supported_snippet_version: __v.vs_supported_snippet_version.unwrap_or_default(),
            vs_supports_not_including_text_in_text_document_did_open: __v
                .vs_supports_not_including_text_in_text_document_did_open
                .unwrap_or_default(),
            vs_supports_icon_extensions: __v.vs_supports_icon_extensions.unwrap_or_default(),
            vs_supports_diagnostic_requests: __v
                .vs_supports_diagnostic_requests
                .unwrap_or_default(),
        }
    }
}

