impl Position {
    /// `func (s *Position) Compare(other *Position) int`
    pub fn compare(&self, other: &Position) -> i32 {
        self.line.cmp(&other.line) as i32 * (self.line != other.line) as i32
            + self.character.cmp(&other.character) as i32
    }
}

impl Range {
    /// `func (s *Range) Compare(other *Range) int`
    pub fn compare(&self, other: &Range) -> i32 {
        let c = self.start.compare(&other.start);
        if c != 0 {
            return c;
        }
        self.end.compare(&other.end)
    }
}

impl TextEdit {
    /// `func (s *TextEdit) Compare(other *TextEdit) int`
    pub fn compare(&self, other: &TextEdit) -> i32 {
        let c = self.range.compare(&other.range);
        if c != 0 {
            return c;
        }
        match self.new_text.cmp(&other.new_text) {
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => 0,
            std::cmp::Ordering::Greater => 1,
        }
    }
}
